        [Test]
        public void ASlowPressThroughIsLetGoWithBoundedTurnsAndNoShake()
        {
            Replay(SlowPress, SlowPressStartSeconds);
        }

        [Test]
        public void AFastSweepThroughAndBackIsLetGoWithBoundedTurnsAndNoShake()
        {
            Replay(FastSweep, FastSweepStartSeconds);
        }

        private static void Replay(float[,] rows, double startSeconds)
        {
            var solver = new BladeContactSolver();
            var trace = new GiveTrace();
            var settings = new BladeSettings();
            var deepest = 0.0f;
            var deepestSeconds = 0.0;
            var pressedFrames = 0;
            var now = startSeconds;
            for (var row = 0; row < rows.GetLength(0); row++)
            {
                var deltaSeconds = rows[row, 0];
                now += deltaSeconds;
                var mine = ToHold(rows, row, 1, settings);
                var partner = ToHold(rows, row, 7, settings);
                solver.Solve(mine, partner, deltaSeconds);
                trace.Add(now, mine.Chord, solver.GiveA, partner.Chord, solver.GiveB, solver.IsInContact ? solver.PressMeters : 0.0f);
                if (solver.IsInContact)
                {
                    pressedFrames++;
                    if (solver.PressMeters > deepest)
                    {
                        deepest = solver.PressMeters;
                        deepestSeconds = now;
                    }
                }

                TestContext.WriteLine(FormattableString.Invariant(
                    $"{now:0.000} press {(solver.IsInContact ? solver.PressMeters * 100 : 0):0.0} cm, turn {solver.GiveA.TurnDegrees:0}/{solver.GiveB.TurnDegrees:0}, bow {solver.GiveA.BowMeters * 100:0.0}/{solver.GiveB.BowMeters * 100:0.0} cm, jump {trace.LastJumpA * 100:0.0}/{trace.LastJumpB * 100:0.0} cm, at {solver.FractionA:0.00}/{solver.FractionB:0.00}, saturated {solver.SaturatedStages}, sliding {solver.SlidingBlade}, returning {solver.ReturningBlade}, through {solver.IsThrough}, side {solver.Side?.X:0.00} {solver.Side?.Y:0.00} {solver.Side?.Z:0.00}"));
            }

            var context = FormattableString.Invariant($"Pressed {pressedFrames} frames, deepest {deepest * 100:0.0} cm at {deepestSeconds:0.000} s.");
            TestContext.WriteLine(trace + " " + context);
            Assert.That(pressedFrames, Is.GreaterThan(0), "Setup: the blades press.");
            trace.AssertBounded(context);
            Assert.That(deepest, Is.LessThanOrEqualTo(DeepCrossingTests.MostThroughMeters), "Never pressed on past the through depth: let go there. " + context);
        }

        /// <summary>The blade from the guard at <paramref name="column"/> to the real point after it, as a Fencer holds it.</summary>
        private static BladeHold ToHold(float[,] rows, int row, int column, BladeSettings settings)
        {
            var guard = new Vector3(rows[row, column], rows[row, column + 1], rows[row, column + 2]);
            var point = new Vector3(rows[row, column + 3], rows[row, column + 4], rows[row, column + 5]);
            var chord = new BladeSegment(guard, point);
            var droop = BladeDroop.Create(chord.Direction, Vector3.UnitY, -Vector3.UnitY, settings);
            return new BladeHold(chord, droop, BladeContactSolver.FencerGripStiffness, BladeContactSolver.GetBendStiffness(BladeFlexSoftness.Normal));
        }
    }
}
